export function getHematologiaConteudo(id) {
  if (!id) return '';
  const norm = id.trim().toLowerCase();
  const slug = norm.replace(/_/g, '-');
  return HEMATOLOGIA_CONDUTAS_MAP[norm] || HEMATOLOGIA_CONDUTAS_MAP[slug] || '';
}
